#include <iostream>
#include <vector>
#include <numeric>
#include <string>
int main() {
    std::vector<int> v = {1,2,3,4,5};
    std::cout << "sum = " << std::accumulate(v.begin(), v.end(), 0) << '\n';
    std::cout << "sum*2 = " << std::accumulate(v.begin(), v.end(), 0, [](int s, int x){ return s + x * 2; }) << '\n';
    std::vector<std::string> w = {"a","b","c"};
    std::string s = std::accumulate(w.begin(), w.end(), std::string(""));
    std::cout << "join = " << s << '\n';
}
